'use client';
/* eslint-disable */
// Generated by scripts/convert-designs.mjs from design/landing-page/MissionTwin.template.html — edit the design or the patches, then re-run.
import React from 'react';
import Link from 'next/link';
import Base from './_base';
import { AppRail, TopBar } from '@/components/chrome';
import { getPillar, setPillar, readJSON, writeJSON, signIn, signOut, saveSession, downloadFile } from '@/lib/store';
import { API_URL, pingApi, inferFile, submitRequest } from '@/lib/api';
import { sessionData } from '@/lib/session';
import './css/MissionTwin.css';

class View extends Base {
  constructor(props) {
    super(props);
    this._dataOverride = sessionData(props.id, this.__data());
    const P0 = props.pillar || 'energy', D0 = this._data().P[P0];
    this.state = { pillar: P0, sel: props.detectionId || (D0.dets[0] ? D0.dets[0].id : null), filter: 'all', view: 'orbit', playing: false, speed: 1, ticks: [], layers: { terrain: true, path: true, dets: true, overlay: true } };
  }

  renderVals() {
    const D = this._data();
    const { pillar, sel, filter, view, playing, speed, ticks, layers } = this.state;
    const pc = D.P[pillar];
    const all = pc.dets;
    const q = all.find((x) => x.id === sel) || null;
    const list = filter === 'all' ? all : all.filter((x) => x.sev === filter);
    const rescue = pillar === 'rescue';
    const pick = (k) => {
      const first = D.P[k].dets[0] ? D.P[k].dets[0].id : null;
      this.setState({ pillar: k, sel: first, filter: 'all' });
      window.history.replaceState(null, '', '/missions/' + D.P[k].mission);
      if (this._twin) { this._twin.setPillar(k); this._twin.select(first); this.setState({ ticks: this._twin.markers() }); }
    };
    const blank = { id: '', cls: '', confStr: '', thumb: '', tag: '', frame: '', sevBadge: '', sevLabel: '', status: '', statusCls: '', confW: '0%', kv: [], primaryAction: '', resolveLabel: '' };
    return {
      pillars: this._pillarTabs(pillar, pick),
      pc,
      stats: [
        { k: 'Frames', v: String(pc.frames), cls: '' },
        { k: rescue ? 'Signatures' : 'Detections', v: all.length + ' priority', cls: '' },
        { k: 'Critical', v: String(all.filter((x) => x.sev === 'crit').length), cls: 'crit' },
        { k: 'Model', v: pc.model, cls: '' },
      ],
      layerList: [['terrain', 'Terrain'], ['path', rescue ? 'Search path' : 'Flight path'], ['dets', rescue ? 'Signatures' : 'Detections'], ['overlay', pc.overlay.replace(' overlay', '')]].map(([k, name]) => ({
        name, cls: layers[k] ? 'on' : '', toggle: () => {
          const next = Object.assign({}, this.state.layers, { [k]: !this.state.layers[k] });
          this.setState({ layers: next });
          if (this._twin) this._twin.setLayers(next);
        },
      })),
      listLbl: rescue ? 'Heat signatures' : 'Detections',
      filters: [['all', 'All'], ['crit', 'Crit'], ['warn', 'Warn']].map(([k, name]) => ({ name, cls: filter === k ? 'on' : '', pick: () => this.setState({ filter: k }) })),
      rows: list.map((x) => ({ cls: x.cls, loc: x.loc, confStr: x.conf.toFixed(2), sevCls: x.sevCls, selCls: x.id === sel ? 'sel' : '', pick: () => this._select(x.id) })),
      hasSel: !!q,
      noSel: !q,
      det: q ? {
        id: q.id, cls: q.cls, confStr: q.conf.toFixed(2), thumb: pc.thumb, tag: q.cls.toUpperCase() + ' ' + q.conf.toFixed(2), frame: q.frame,
        sevBadge: q.sev === 'crit' ? 'b-crit' : 'b-sim', sevLabel: q.sevLabel, status: q.status, statusCls: q.statusCls, confW: q.confPct + '%',
        primaryAction: rescue ? 'Dispatch team' : 'Assign to crew', resolveLabel: rescue ? 'Confirm found' : 'Mark resolved',
        kv: [
          ['Location', q.loc], ['Latitude', q.lat, 'Manifest'], ['Longitude', q.lon, 'Manifest'],
          ['World offset', 'E ' + q.offX + ' m · N ' + q.offZ + ' m'], ['Capture alt.', q.alt + ' AGL'], ['Heading', q.hdg],
          ['Frame', q.frame + ' · RGB'], ['Model', pc.model], ['BBox xyxy', q.bbox.join(', ')], ['Detected', q.ago],
        ].map(([k, v, badge]) => ({ k, v, badge: badge || '', hasBadge: !!badge })),
      } : blank,
      closeSel: () => this._select(null),
      ctlCls: q ? 'ctl shifted' : 'ctl',
      views: [['orbit', '3D'], ['top', 'Top'], ['follow', 'Follow']].map(([k, name]) => ({
        name, cls: view === k ? 'on' : '', pick: () => { this.setState({ view: k }); if (this._twin) this._twin.setView(k); },
      })),
      zoomIn: () => this._twin && this._twin.zoom(0.8),
      zoomOut: () => this._twin && this._twin.zoom(1.25),
      resetView: () => { if (this._twin) this._twin.resetView(); this.setState({ view: 'orbit', sel: null }); },
      isPlaying: playing,
      notPlaying: !playing,
      togglePlay: () => { if (!this._twin) return; const p = !this._twin.isPlaying(); this._twin.setPlaying(p); this.setState({ playing: p }); },
      speeds: [1, 2, 4].map((s) => ({ name: s + '×', cls: speed === s ? 'on' : '', pick: () => { this.setState({ speed: s }); if (this._twin) this._twin.setSpeed(s); } })),
      ticks: ticks.map((m) => ({
        left: (m.frac * 100).toFixed(2) + '%', cls: m.sev === 'crit' ? 'sev-crit' : 'sev-warn', selCls: m.id === sel ? 'on' : '',
        pick: () => { this._select(m.id, true); if (this._twin) this._twin.setTime(Math.min(1, m.frac + 0.01)); },
      })),
      trackDown: (e) => this._scrub(e),
    };
  }

  _select(id, force) {
    const next = !force && this.state.sel === id ? null : id;
    this.setState({ sel: next });
    if (this._twin) this._twin.select(next);
  }

  _scrub(e) {
    if (!this._twin || (e.target && e.target.closest && e.target.closest('.tl-tick'))) return;
    const track = e.currentTarget;
    const set = (cx) => { const r = track.getBoundingClientRect(); this._twin.setTime((cx - r.left) / Math.max(1, r.width)); };
    set(e.clientX);
    const move = (ev) => set(ev.clientX);
    const up = () => { window.removeEventListener('pointermove', move); window.removeEventListener('pointerup', up); };
    window.addEventListener('pointermove', move);
    window.addEventListener('pointerup', up);
  }

  componentDidMount() {
    this._syncPillar();
    this._alive = true;
    this._startClock();
    this._boot(0);
  }

  componentWillUnmount() {
    this._alive = false;
    this._stopClock();
    if (this._raf) cancelAnimationFrame(this._raf);
    if (this._twin) this._twin.destroy();
  }

  _boot(tries) {
    if (!this._alive) return;
    const canvas = document.querySelector('[data-gl="twin"]');
    if (!canvas) { if (tries < 120) requestAnimationFrame(() => this._boot(tries + 1)); return; }
    const hud = {};
    ['lat', 'lon', 'hdg', 'lane', 'time', 'cov', 'prog', 'head'].forEach((k) => { hud[k] = document.querySelector('[data-hud="' + k + '"]'); });
    const FLIGHT = 860;
    this._twin = this._twinScene(this._engine(), canvas, {
      pillar: this.state.pillar,
      mode: 'mission',
      labelsEl: document.querySelector('[data-gl-labels="twin"]'),
      onPick: (id) => this._select(id, true),
      onHud: (h) => {
        ['lat', 'lon', 'hdg', 'lane'].forEach((k) => { if (hud[k]) hud[k].textContent = h[k]; });
        const s = Math.round(h.frac * FLIGHT);
        if (hud.time) hud.time.textContent = 'T+' + String(Math.floor(s / 60)).padStart(2, '0') + ':' + String(s % 60).padStart(2, '0');
        if (hud.cov) hud.cov.textContent = Math.round(h.cov) + '%';
        const pct = (h.frac * 100).toFixed(2) + '%';
        if (hud.prog) hud.prog.style.width = pct;
        if (hud.head) hud.head.style.left = pct;
        if (h.playing !== this.state.playing) this.setState({ playing: h.playing });
      },
    });
    if (this._twin) {
      this._twin.select(this.state.sel);
      this.setState({ ticks: this._twin.markers() });
    }
    this._loop([this._twin]);
  }



  render() {
    const v = this.renderVals();
    return (
      <div className="pg-mission-twin ds">
        <div className="app">
          <AppRail active="missions" />
          <TopBar crumbs={["Missions","Mission twin"]} pillars={v.pillars} />
          <main className="main">
            <div className="stage">
              <canvas className="gl" data-gl="twin"></canvas>
              <div className="vignette"></div>
              <div className="gl-labels" data-gl-labels="twin"></div>
              <aside className="glass mis">
                <div className="mis-head">
                  <div className="kicker" style={{ color: `${v.pc?.color ?? ""}` }}>
                    <i></i>
                    {v.pc?.name}{" · "}{v.pc?.long}
                  </div>
                  <h1 className="h1 mis-id">
                    {v.pc?.mission}
                  </h1>
                  <div className="mis-site">
                    {v.pc?.site}
                  </div>
                  <div className="meta" style={{ marginTop: "4px" }}>
                    {v.pc?.date}{" UTC · Rajkot AO"}
                  </div>
                  <div className="mis-badges">
                    <span className="badge b-sim">
                      {"Simulated telemetry"}
                    </span>
                    <span className="badge b-man">
                      {"Manifest positions"}
                    </span>
                  </div>
                </div>
                <div className="stats">
                  {(v.stats || []).map((s, $index) => (
                    <React.Fragment key={$index}>
                    <div className="stat">
                      <span className="lbl">
                        {s?.k}
                      </span>
                      <b className={s?.cls}>
                        {s?.v}
                      </b>
                    </div>
                    </React.Fragment>
                  ))}
                </div>
                <div className="sect">
                  <span className="lbl">
                    {"Layers"}
                  </span>
                  <div className="layer-grid">
                    {(v.layerList || []).map((l, $index) => (
                      <React.Fragment key={$index}>
                      <button className={`ck ${l?.cls ?? ""}`} onClick={l?.toggle}>
                        <i></i>
                        {l?.name}
                      </button>
                      </React.Fragment>
                    ))}
                  </div>
                </div>
                <div className="sect sect-row">
                  <span className="lbl">
                    {v.listLbl}
                  </span>
                  <div className="segs">
                    {(v.filters || []).map((f, $index) => (
                      <React.Fragment key={$index}>
                      <button className={f?.cls} onClick={f?.pick}>
                        {f?.name}
                      </button>
                      </React.Fragment>
                    ))}
                  </div>
                </div>
                <div className="scroll dl">
                  {(v.rows || []).map((r, $index) => (
                    <React.Fragment key={$index}>
                    <button className={`drow ${r?.selCls ?? ""}`} onClick={r?.pick}>
                      <i className={`dia ${r?.sevCls ?? ""}`}></i>
                      <span style={{ minWidth: "0" }}>
                        <span className="drow-t">
                          {r?.cls}
                        </span>
                        <span className="drow-s">
                          {r?.loc}
                        </span>
                      </span>
                      <span className="drow-c">
                        {r?.confStr}
                      </span>
                    </button>
                    </React.Fragment>
                  ))}
                </div>
              </aside>
              <div className={v.ctlCls}>
                <div className="glass">
                  <div className="segs">
                    {(v.views || []).map((v, $index) => (
                      <React.Fragment key={$index}>
                      <button className={v?.cls} onClick={v?.pick}>
                        {v?.name}
                      </button>
                      </React.Fragment>
                    ))}
                  </div>
                </div>
                <div className="glass">
                  <button className="zbtn" onClick={v.zoomIn}>
                    {"+"}
                  </button>
                  <button className="zbtn" onClick={v.zoomOut}>
                    {"−"}
                  </button>
                  <button className="zbtn" onClick={v.resetView}>
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6">
                      <path d="M4 12a8 8 0 108-8H7"></path>
                      <path d="M9 1L6 4l3 3"></path>
                    </svg>
                  </button>
                </div>
              </div>
              {v.noSel ? (
                <>
                <div className="glass hint">
                  <span className="lbl">
                    {"Inspection dossier"}
                  </span>
                  {"Select a marker in the twin or a row in the list to open its dossier. Drag to orbit the site."}
                </div>
                </>
              ) : null}
              {v.hasSel ? (
                <>
                <aside className="glass dossier">
                  <div className="ds-head">
                    <span className={`badge ${v.det?.sevBadge ?? ""}`}>
                      {v.det?.sevLabel}
                    </span>
                    <span className="mono ds-id">
                      {v.det?.id}
                    </span>
                    <button className="ds-x" onClick={v.closeSel}>
                      <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6">
                        <path d="M6 6l12 12M18 6L6 18"></path>
                      </svg>
                    </button>
                  </div>
                  <div className="scroll ds-body">
                    <span className="lbl">
                      {"Inspection dossier"}
                    </span>
                    <div className="ds-title">
                      <h2 className="h2">
                        {v.det?.cls}
                      </h2>
                      <b>
                        {v.det?.confStr}
                      </b>
                    </div>
                    <div className={`frame thumb ${v.det?.thumb ?? ""}`}>
                      <span className="fbox">
                        <b>
                          {v.det?.tag}
                        </b>
                      </span>
                      <span className="f-cross"></span>
                      <span className="f-tl">
                        {v.det?.frame}{" · crop"}
                      </span>
                      <span className="f-scale">
                        <i></i>
                        {"~2 m"}
                      </span>
                      <span className="badge b-sim f-br">
                        {"Sample frame"}
                      </span>
                    </div>
                    <div className="conf">
                      <div className="conf-top">
                        <span className="lbl">
                          {"Model confidence"}
                        </span>
                        <span className={`chip ${v.det?.statusCls ?? ""}`}>
                          {v.det?.status}
                        </span>
                      </div>
                      <div className="conf-bar">
                        <b style={{ width: `${v.det?.confW ?? ""}` }}></b>
                        <i></i>
                      </div>
                      <div className="conf-note">
                        {"Amber mark = inference threshold 0.50"}
                      </div>
                    </div>
                    <div className="kv">
                      {(v.det?.kv || []).map((row, $index) => (
                        <React.Fragment key={$index}>
                        <div className="kv-row">
                          <span>
                            {row?.k}
                          </span>
                          <b>
                            {row?.v}
                          </b>
                          {row?.hasBadge ? (
                            <>
                            <em className="badge b-man" style={{ fontStyle: "normal" }}>
                              {row?.badge}
                            </em>
                            </>
                          ) : null}
                        </div>
                        </React.Fragment>
                      ))}
                    </div>
                    <div className="prov">
                      <i className="dia sev-warn"></i>
                      <span>
                        {"Position comes from the flight manifest, not recorded GPS. Treat it as approximate, not survey-grade."}
                      </span>
                    </div>
                  </div>
                  <div className="ds-actions">
                    <button className="btn btn-primary wide" onClick={() => alert(`Work order assigned for anomaly ${v.det?.id || ''}. Notification sent to field team.`)}>
                      {v.det?.primaryAction}
                    </button>
                    <button className="btn btn-ghost" onClick={() => alert(`Anomaly ${v.det?.id || ''} marked as resolved.`)}>
                      {v.det?.resolveLabel}
                    </button>
                    <button className="btn btn-ghost" onClick={() => { navigator.clipboard?.writeText?.('-22.9519, 15.0234'); alert('Coordinates copied to clipboard: -22.9519, 15.0234'); }}>
                      {"Copy coordinates"}
                    </button>
                  </div>
                </aside>
                </>
              ) : null}
              <div className="readout">
                {"DRONE "}
                <b data-hud="lat">
                  {"22.30000° N"}
                </b>
                {" "}
                <b data-hud="lon">
                  {"70.80000° E"}
                </b>
                {" · HDG "}
                <b data-hud="hdg">
                  {"090°"}
                </b>
                {" "}
                <span className="amber">
                  {"±APPROX."}
                </span>
              </div>
              <div className="glass tl">
                <button className="tl-play" onClick={v.togglePlay}>
                  {v.isPlaying ? (
                    <>
                    <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor">
                      <rect x="6" y="5" width="4" height="14"></rect>
                      <rect x="14" y="5" width="4" height="14"></rect>
                    </svg>
                    </>
                  ) : null}
                  {v.notPlaying ? (
                    <>
                    <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor">
                      <path d="M7 4.5v15l12-7.5z"></path>
                    </svg>
                    </>
                  ) : null}
                </button>
                <div className="tl-time">
                  <b data-hud="time">
                    {"T+11:43"}
                  </b>
                  <span>
                    {"/ 14:20"}
                  </span>
                  <em>
                    {"Flight time · sample"}
                  </em>
                </div>
                <div className="tl-track" onPointerDown={v.trackDown}>
                  <div className="tl-ticks"></div>
                  <div className="tl-rail"></div>
                  <div className="tl-fill" data-hud="prog"></div>
                  {(v.ticks || []).map((m, $index) => (
                    <React.Fragment key={$index}>
                    <button className={`tl-tick ${m?.selCls ?? ""}`} style={{ left: `${m?.left ?? ""}` }} onClick={m?.pick}>
                      <i className={`dia ${m?.cls ?? ""}`}></i>
                    </button>
                    </React.Fragment>
                  ))}
                  <div className="tl-head" data-hud="head"></div>
                </div>
                <div className="segs">
                  {(v.speeds || []).map((s, $index) => (
                    <React.Fragment key={$index}>
                    <button className={s?.cls} onClick={s?.pick}>
                      {s?.name}
                    </button>
                    </React.Fragment>
                  ))}
                </div>
                <div className="tl-read">
                  {"LANE "}
                  <b data-hud="lane">
                    {"7 / 7"}
                  </b>
                  {" · COVERAGE "}
                  <b data-hud="cov">
                    {"100%"}
                  </b>
                </div>
                <Link className="btn btn-primary" href={'/missions/' + v.pc.mission + '/report'}>
                  {"Generate report →"}
                </Link>
              </div>
            </div>
          </main>
        </div>
      </div>
    );
  }
}

export default View;
